from collections import deque

def solve():
    data = sys.stdin.buffer.read().split()
    N = int(data[0])
    C = [data[1+i].decode() for i in range(N)]

    in_by_label_u = [{} for _ in range(N)]
    out_by_label_v = [{} for _ in range(N)]

    for i in range(N):
        row = C[i]
        for j in range(N):
            c = row[j]
            if c != '-':
                out_by_label_v[i].setdefault(c, []).append(j)
                in_by_label_u[j].setdefault(c, []).append(i)

    def bfs(initial):
        dist = [[-1]*N for _ in range(N)]
        q = deque()
        for (u, v, d) in initial:
            if dist[u][v] == -1:
                dist[u][v] = d
                q.append((u, v))
        while q:
            u, v = q.popleft()
            d = dist[u][v]
            nd = d + 2
            ibl = in_by_label_u[u]
            obl = out_by_label_v[v]
            if not ibl or not obl:
                continue
            if len(ibl) <= len(obl):
                for c, ups in ibl.items():
                    vps = obl.get(c)
                    if vps is None:
                        continue
                    for up in ups:
                        row = dist[up]
                        for vp in vps:
                            if row[vp] == -1:
                                row[vp] = nd
                                q.append((up, vp))
            else:
                for c, vps in obl.items():
                    ups = ibl.get(c)
                    if ups is None:
                        continue
                    for up in ups:
                        row = dist[up]
                        for vp in vps:
                            if row[vp] == -1:
                                row[vp] = nd
                                q.append((up, vp))
        return dist

    even_init = [(i, i, 0) for i in range(N)]
    dist_even = bfs(even_init)

    odd_init = []
    for i in range(N):
        for j in range(N):
            if C[i][j] != '-':
                odd_init.append((i, j, 1))
    dist_odd = bfs(odd_init)

    out_lines = []
    for i in range(N):
        row = []
        for j in range(N):
            de = dist_even[i][j]
            do = dist_odd[i][j]
            if de == -1 and do == -1:
                row.append(-1)
            elif de == -1:
                row.append(do)
            elif do == -1:
                row.append(de)
            else:
                row.append(de if de < do else do)
        out_lines.append(' '.join(map(str, row)))
    sys.stdout.write('\n'.join(out_lines) + '\n')

solve()

